// Combine and generate expansive items for all 15 categories to form the 1,000+ dataset
const ALL_ITEMS = [];
let idCounter = 1;

for (const catObj of RAW_CATEGORIES) {
  for (const w of catObj.words) {
    ALL_ITEMS.push({
      id: `ielts-${idCounter++}`,
      word: w[0],
      category: catObj.category,
      partOfSpeech: catObj.pos,
      level: catObj.level,
      meaning: w[2],
      phonetic: w[1],
      exampleSentence: w[3],
      commonMisspellings: w[4] || [],
      commonPhrases: w[5] || [],
      isIELTSCommon: true,
    });
  }
}

